import { http } from '@/shared/api/httpClient';
import type { HomeData, Page, SortKey, TitleListItem } from '@/shared/api/types';

export interface SearchParams {
  q?: string;
  genres?: number[];
  sort?: SortKey;
  year?: number;
  cursor?: string;
  limit?: number;
}

export function searchTitles(params: SearchParams, signal?: AbortSignal): Promise<Page<TitleListItem>> {
  return http.get<Page<TitleListItem>>('/search', {
    query: {
      q: params.q,
      genres: params.genres,
      sort: params.sort,
      year: params.year,
      cursor: params.cursor,
      limit: params.limit,
    },
    signal,
  });
}

export function fetchHome(): Promise<HomeData> {
  return http.get<HomeData>('/home');
}
