import { onBeforeUnmount, onMounted, type Ref } from 'vue';

/**
 * Invokes `callback` when `target` scrolls into view — used to trigger
 * infinite-list loading. Returns nothing; wire the target ref in the template.
 */
export function useIntersection(target: Ref<Element | null>, callback: () => void): void {
  let observer: IntersectionObserver | null = null;

  onMounted(() => {
    if (!target.value) return;
    observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) if (entry.isIntersecting) callback();
      },
      { rootMargin: '400px 0px' },
    );
    observer.observe(target.value);
  });

  onBeforeUnmount(() => observer?.disconnect());
}
